// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.stt.whisperimport timber.log.Timberimport android.app.ActivityManagerimport android.content.Contextimport android.os.Build/** * NOUS — Whisper.cpp Configuration + Model Selector. * * Picks the best whisper.cpp model for this device and exposes a * [WhisperConfig] that the [WhisperSttEngine] consumes. Mirrors the * app-heap-aware pattern from Module 4's `QuantizationSelector`. * * ## Model selection (§6 Whisper.cpp JNI Bridge) * * | Model      | Size  | Accuracy | Use case                                  | * |------------|-------|----------|-------------------------------------------| * | tiny.en    | 39 MB | ~85%     | Survival mode (SEVERE thermal, low RAM)   | * | base.en    | 75 MB | ~92%     | Default for English-only devices          | * | small      | 250MB | ~96%     | High-RAM devices, multi-lingual users     | * | small.q5_1 | 100MB | ~95%     | Balanced — recommended default            | * * ## App-heap-aware (NOT total RAM) * * Per Module 4's v2.1 fix #5: Android gives each app a heap limit * (192-512 MB normal, up to 1 GB largeHeap). Loading a 250 MB model when * the app heap is 256 MB will OOM-kill the app. We use * [ActivityManager.memoryClass] — not `Runtime.totalMemory()` — to pick * the largest model that fits. * * ## CPU threads * * Whisper.cpp is CPU-bound (Vulkan GPU helps but isn't always available). * We use 1-4 threads based on CPU core count, but never more than 2 on * devices with `THERMAL_STATUS_LIGHT` or higher (per §16 Thermal * Throttling) to avoid thermal throttling death-spirals. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§6 Whisper.cpp JNI Bridge, §16 Battery & Thermal Management</a> */data class WhisperConfig(    /** Absolute path to the .gguf model file on disk. */    val modelPath: String,    /** ISO 639-1 language code ("en", "hi", "auto"). */    val language: String = "auto",    /** Number of CPU threads (1-4; device-aware). */    val threads: Int = DEFAULT_THREADS,    /** Whether to use Vulkan GPU acceleration. */    val useGpu: Boolean = true,    /** Enable speed-up mode (1.5-2× faster, slightly lower accuracy). */    val speedUp: Boolean = true,    /** Translate non-English speech to English text. */    val translate: Boolean = false,) {    init {        require(threads in 1..8) { "threads must be 1..8, got $threads" }    }    companion object {        /** Default thread count — overridden by [WhisperModelSelector] per-device. */        const val DEFAULT_THREADS = 2    }}// ──────────────────────────────────────────────────────────────────────────/** * Picks the best whisper.cpp model for this device. * * Selection logic: *  1. Probe app heap (NOT total RAM — see Module 4 v2.1 fix #5). *  2. Probe CPU cores. *  3. Probe GPU VRAM (via JNI, if native lib loaded). *  4. Pick model + quantization + threads. * * The caller (e.g. the Hilt module in Step 5.14) is responsible for * downloading the selected model if it's not already on disk. The * [LocalLlmModelCatalog]-equivalent for whisper ships in Step 5.14. */object WhisperModelSelector {    /**     * Recommend a [WhisperConfig] for this device.     *     * @param context        application context (for ActivityManager)     * @param modelDirectory absolute path to the directory where whisper     *                       models are stored     *                       (e.g. `/data/user/0/com.roshan.persona/files/whisper/`)     * @param preferGpu      whether the user has enabled GPU acceleration in     *                       Settings (default true)     */    fun recommend(        context: Context,        modelDirectory: String,        preferGpu: Boolean = true,    ): WhisperConfig {        val appHeapMb = getAppHeapMb(context)        val cpuCores = Runtime.getRuntime().availableProcessors()        val gpuAvailable = preferGpu && probeGpuAvailable()        val gpuVramMb = if (gpuAvailable) probeGpuVramMb() else 0        // Model selection — app-heap-aware.        val model = when {            appHeapMb >= 512 && gpuVramMb >= 200 -> Model.SMALL_Q5_1   // 100 MB, balanced            appHeapMb >= 384 -> Model.BASE_EN                            // 75 MB, English-only            appHeapMb >= 256 -> Model.TINY_EN                            // 39 MB, survival            else -> Model.TINY_EN                                       // forced — better than nothing        }        // Thread selection — never use all cores (leaves room for audio + UI).        val threads = when {            cpuCores >= 8 -> 4            cpuCores >= 6 -> 3            cpuCores >= 4 -> 2            else -> 1        }        // Speed-up mode: enable on devices where it doesn't hurt accuracy        // (4+ cores, no thermal throttling). Disable on low-end devices        // where speed-up causes unacceptable quality loss.        val speedUp = cpuCores >= 4        val path = "$modelDirectory/${model.fileName}"        Timber.tag(TAG).i("Whisper model selected: ${model.fileName} " +            "(heap=${appHeapMb}MB, cores=$cpuCores, gpu=$gpuAvailable, threads=$threads)")        return WhisperConfig(            modelPath = path,            language = "auto",            threads = threads,            useGpu = gpuAvailable,            speedUp = speedUp,            translate = false,        )    }    // ─── Probes ─────────────────────────────────────────────────────────    /** Get app heap limit in MB (NOT total device RAM). */    fun getAppHeapMb(context: Context): Int {        val am = context.getSystemService(Context.ACTIVITY_SERVICE) as? ActivityManager            ?: return DEFAULT_APP_HEAP_MB        return am.memoryClass    }    /** Get largeHeap limit in MB (if `android:largeHeap="true"`). */    fun getLargeHeapMb(context: Context): Int {        val am = context.getSystemService(Context.ACTIVITY_SERVICE) as? ActivityManager            ?: return DEFAULT_APP_HEAP_MB        return am.largeMemoryClass    }    /** Probe Vulkan GPU availability via JNI. */    private fun probeGpuAvailable(): Boolean {        if (!WhisperJni.ensureLoaded()) return false        return runCatching { WhisperJni.nativeIsGpuAvailable() }.getOrDefault(false)    }    /** Probe GPU VRAM in MB. */    private fun probeGpuVramMb(): Int {        if (!WhisperJni.ensureLoaded()) return 0        return runCatching { WhisperJni.nativeGetGpuVramMb() }.getOrDefault(0)    }    // ─── Model catalog ──────────────────────────────────────────────────    /**     * Whisper.cpp model variants supported by NOUS.     *     * File names match the official whisper.cpp releases on HuggingFace     * (`ggml-*.bin` or `ggml-*-q5_1.bin` for quantized variants).     */    enum class Model(        val fileName: String,        val sizeMb: Int,        val englishOnly: Boolean,        val expectedAccuracy: Float,    ) {        TINY_EN("ggml-tiny.en.bin", 39, true, 0.85f),        BASE_EN("ggml-base.en.bin", 75, true, 0.92f),        SMALL_Q5_1("ggml-small-q5_1.bin", 100, false, 0.95f),        SMALL("ggml-small.bin", 250, false, 0.96f);        /** True if this model supports languages other than English. */        val isMultilingual: Boolean get() = !englishOnly    }    private const val TAG = "WhisperModelSelector"    private const val DEFAULT_APP_HEAP_MB = 256}